  "j-07": {
    "control_id": "j-07",
    "risks": [
      {
        "typical_impact": 4,
        "title_de": "Unautorisierter Zugriff durch kompromittierte Anmeldeinformationen",
        "title_en": "Unauthorized access due to compromised credentials",
        "description_de": "Ein Angreifer erlangt durch Phishing oder Malware Anmeldeinformationen eines Mitarbeiters und kann sich unbemerkt im Netzwerk bewegen, da keine weiteren Verifizierungen erfolgen, was zu Datenlecks oder Systemausfällen führen kann.",
        "threat_category": "Phishing",
        "description_en": "An attacker obtains an employee's credentials through phishing or malware and can move unnoticed within the network because no further verifications are performed, which can lead to data breaches or system failures.",
        "typical_likelihood": 4,
        "cia": [
          "C",
          "I",
          "A"
        ],
        "id": "j-07-r1"
      },
      {
        "title_de": "Laterale Bewegung von Angreifern im internen Netzwerk",
        "typical_impact": 5,
        "threat_category": "Misconfiguration",
        "description_en": "After an initial breach, an attacker can spread unhindered within the internal network due to a lack of network segmentation and insufficient access controls, compromising critical systems and causing widespread damage.",
        "description_de": "Nach einem initialen Einbruch kann sich ein Angreifer aufgrund fehlender Netzwerksegmentierung und unzureichender Zugriffskontrollen ungehindert im internen Netzwerk ausbreiten, kritische Systeme kompromittieren und weitreichende Schäden verursachen.",
        "typical_likelihood": 3,
        "cia": [
          "C",
          "I",
          "A"
        ],
        "title_en": "Lateral movement of attackers within the internal network",
        "id": "j-07-r2"
      },
      {
        "typical_impact": 4,
        "title_de": "Datenexfiltration durch Insider-Bedrohungen",
        "title_en": "Data exfiltration by insider threats",
        "description_en": "A privileged insider abuses their access rights to exfiltrate sensitive data from the network because no context-based access control or continuous monitoring of data access is implemented, leading to significant reputational and financial damage.",
        "threat_category": "Insider",
        "description_de": "Ein privilegierter Insider missbraucht seine Zugriffsrechte, um sensible Daten aus dem Netzwerk zu exfiltrieren, da keine kontextbezogene Zugriffskontrolle oder kontinuierliche Überwachung der Datenzugriffe implementiert ist, was zu erheblichen Reputations- und finanziellen Schäden führt.",
        "typical_likelihood": 2,
        "cia": [
          "C",
          "I"
        ],
        "id": "j-07-r3"
      },
      {
        "typical_impact": 4,
        "title_de": "Unentdeckte Kompromittierung von IoT/OT-Geräten",
        "title_en": "Undetected compromise of IoT/OT devices",
        "description_de": "Angreifer kompromittieren schlecht gesicherte IoT- oder OT-Geräte im Netzwerk, die aufgrund fehlender Mikrosegmentierung und unzureichender Überwachung als Einfallstor für weitere Angriffe auf kritische Infrastrukturen genutzt werden können, was zu Betriebsunterbrechungen führt.",
        "threat_category": "Misconfiguration",
        "description_en": "Attackers compromise poorly secured IoT or OT devices in the network, which can be used as an entry point for further attacks on critical infrastructures due to a lack of micro-segmentation and insufficient monitoring, leading to operational disruptions.",
        "typical_likelihood": 3,
        "cia": [
          "C",
          "I",
          "A"
        ],
        "id": "j-07-r4"
      }
    ],
    "measures": [
      {
        "description_en": "All user accesses, both internal and external, must be authenticated by at least two independent factors to ensure user identity before granting access to network resources.",
        "description_de": "Alle Benutzerzugriffe, sowohl intern als auch extern, müssen durch mindestens zwei voneinander unabhängige Faktoren authentifiziert werden, um die Identität des Benutzers sicherzustellen, bevor der Zugriff auf Netzwerkressourcen gewährt wird.",
        "iso_ref": "ISO 27002:2022 A.5.17",
        "priority": "must",
        "title_en": "Implementation of Multi-Factor Authentication (MFA) for all accesses",
        "title_de": "Implementierung einer Multi-Faktor-Authentifizierung (MFA) für alle Zugriffe",
        "bsi_ref": "ORP.4.A8",
        "effort": "medium",
        "id": "j-07-m1"
      },
      {
        "iso_ref": "ISO 27002:2022 A.8.20",
        "title_en": "Network segmentation into micro-segments",
        "priority": "must",
        "description_en": "The corporate network is divided into small, isolated segments, with traffic between these segments explicitly controlled and monitored via firewalls or other security gateways to prevent lateral movement of attackers.",
        "description_de": "Das Unternehmensnetzwerk wird in kleine, isolierte Segmente unterteilt, wobei der Datenverkehr zwischen diesen Segmenten explizit über Firewalls oder andere Sicherheitsgateways geregelt und überwacht wird, um laterale Bewegungen von Angreifern zu verhindern.",
        "effort": "high",
        "title_de": "Segmentierung des Netzwerks in Mikrosektoren",
        "bsi_ref": "NET.1.A5",
        "id": "j-07-m2"
      },
      {
        "effort": "medium",
        "bsi_ref": "ORP.4.A2",
        "title_de": "Einführung des Prinzips der geringsten Privilegien (Least Privilege)",
        "priority": "must",
        "title_en": "Introduction of the Principle of Least Privilege",
        "iso_ref": "ISO 27002:2022 A.5.15",
        "description_de": "Benutzern und Systemen werden nur die minimal notwendigen Berechtigungen zugewiesen, die sie zur Erfüllung ihrer Aufgaben benötigen. Diese Berechtigungen werden regelmäßig überprüft und bei Bedarf angepasst.",
        "description_en": "Users and systems are only assigned the minimum necessary permissions required to perform their tasks. These permissions are regularly reviewed and adjusted as needed.",
        "id": "j-07-m3"
      },
      {
        "description_en": "All network traffic is monitored and analyzed in real-time to detect unusual activities, potential threats, or violations of security policies early and respond accordingly.",
        "description_de": "Der gesamte Netzwerkverkehr wird in Echtzeit überwacht und analysiert, um ungewöhnliche Aktivitäten, potenzielle Bedrohungen oder Verstöße gegen Sicherheitsrichtlinien frühzeitig zu erkennen und darauf reagieren zu können.",
        "iso_ref": "ISO 27002:2022 A.8.16",
        "title_en": "Continuous monitoring and analysis of network traffic",
        "priority": "must",
        "title_de": "Kontinuierliche Überwachung und Analyse des Netzwerkverkehrs",
        "bsi_ref": "OPS.1.A10",
        "effort": "high",
        "id": "j-07-m4"
      },
      {
        "title_de": "Implementierung einer Zugriffsverwaltung basierend auf Kontext und Attributen (ABAC)",
        "bsi_ref": "ORP.4.A2",
        "effort": "high",
        "description_en": "Access decisions are made dynamically based on attributes of the user, resource, environment, and context to ensure granular and flexible access control.",
        "description_de": "Zugriffsentscheidungen werden dynamisch auf Basis von Attributen des Benutzers, der Ressource, der Umgebung und des Kontexts getroffen, um eine granulare und flexible Zugriffskontrolle zu gewährleisten.",
        "iso_ref": "ISO 27002:2022 A.5.15",
        "priority": "should",
        "title_en": "Implementation of Attribute-Based Access Control (ABAC)",
        "id": "j-07-m5"
      }
    ]
  },
