        "id": "iam-mfa-1-m1",
        "title_de": "Hardware-Token / FIDO2 für Admins",
        "title_en": "Hardware tokens / FIDO2 for admins",
        "description_de": "Phishing-resistente MFA (FIDO2/YubiKey) für alle Admin- und Domain-Accounts verpflichtend ausrollen.",
        "description_en": "Roll out phishing-resistant MFA (FIDO2/YubiKey) as mandatory for all admin and domain accounts.",
        "effort": "high",
        "priority": "must",
        "iso_ref": "ISO 27002:2022 A.8.5",
