import {
  reviewRemovedControlIds,
  reviewRemovedRiskIds,
  reviewRevisedRiskMap,
} from "./controlCatalogReview";

/**
 * Apply the 2026-06-12 review overlay:
 *   1. drop out-of-scope controls (9) and their risks
 *   2. drop duplicate / non-infosec risks (33)
 *   3. apply text revisions (25) — EN and DE wording supplied by review.
 *
 * Cross-control additions and measure un-mappings are surfaced via
 * `controlCatalogReview` exports and consumed by engines on demand; they do
 * not mutate the base catalog shape.
 */
function applyReview(
  raw: Record<string, CatalogEntry>,
): Record<string, CatalogEntry> {
  const out: Record<string, CatalogEntry> = {};
  for (const [cid, entry] of Object.entries(raw)) {
    if (reviewRemovedControlIds.has(cid)) continue;
    const risks: CatalogRisk[] = [];
    for (const r of entry.risks) {
      if (reviewRemovedRiskIds.has(r.id)) continue;
      const rev = reviewRevisedRiskMap.get(r.id);
      if (rev) {
        risks.push({
          ...r,
          title_en: rev.new_title_en ?? r.title_en,
          description_en: rev.new_description_en ?? r.description_en,
          title_de: rev.new_title_de ?? r.title_de,
          description_de: rev.new_description_de ?? r.description_de,
        });
      } else {
        risks.push(r);
      }
    }
    out[cid] = { ...entry, risks };
  }
  return out;
}

export const controlCatalog: Record<string, CatalogEntry> = applyReview(rawControlCatalog);

export const getCatalogEntry = (controlId: string): CatalogEntry | undefined =>
  controlCatalog[controlId];

